<?php declare(strict_types=1); $base=config('app.base_path'); $isTrash=!empty($trash); ?><div class="page-header"><div><h1><?= $isTrash?'Deleted Menu Items':'Menu Items' ?></h1><p><?= $isTrash?'Restore food items from Trash.':'Manage prepared food sold by your restaurants.' ?></p></div><div class="page-actions"><?php if($isTrash): ?><a class="btn btn-secondary" href="<?= $base ?>/restaurant/items">Active Items</a><?php else: ?><a class="btn btn-secondary" href="<?= $base ?>/restaurant/items?view=trash">Trash</a><a class="btn btn-primary" href="<?= $base ?>/restaurant/items/create">Add Food Item</a><?php endif; ?></div></div><div class="card"><table class="table"><thead><tr><th>Restaurant</th><th>Item</th><th>Category</th><th>Price</th><th>Veg</th><th>Available</th><th>Actions</th></tr></thead><tbody><?php if(empty($items)): ?><tr><td colspan="7"><div class="empty-state"><?= $isTrash?'Trash is empty.':'No menu items found.' ?></div></td></tr><?php else: foreach($items as $i): ?><tr><td><?= htmlspecialchars((string)$i['restaurant_name'],ENT_QUOTES,'UTF-8') ?></td><td><strong><?= htmlspecialchars((string)$i['name'],ENT_QUOTES,'UTF-8') ?></strong></td><td><?= htmlspecialchars((string)($i['category_name']??'Uncategorized'),ENT_QUOTES,'UTF-8') ?></td><td>₹<?= number_format((float)$i['price'],2) ?></td><td><?= !empty($i['is_veg'])?'Yes':'No' ?></td><td><?= !empty($i['is_available'])?'Yes':'No' ?></td><td><?php if($isTrash): ?><form method="post" action="<?= $base ?>/restaurant/items/<?= (int)$i['id'] ?>/restore"><button class="btn btn-secondary" type="submit">Restore</button></form><?php else: ?><a class="link-button" href="<?= $base ?>/restaurant/items/<?= (int)$i['id'] ?>">View</a> <a class="link-button" href="<?= $base ?>/restaurant/items/<?= (int)$i['id'] ?>/edit">Edit</a><?php endif; ?></td></tr><?php endforeach;endif; ?></tbody></table></div>
